actions.script:
activeOrgId = null
if (ec.user.isInGroup('ADMIN')) {
    def preference = ec.user.getPreference('ACTIVE_ORGANIZATION')
    activeOrgId = preference && preference != '_NA_' ? preference : null
    return
}
// Clear stale derived scope even when this account has no party or resolution fails.
ec.user.context.activeOrgId = null
ec.user.context.userOrgIds = []
ec.user.context.filterOrgIds = []
def callerPartyId = ec.user.userAccount?.partyId
if (!callerPartyId) return
// Only the authoritative relationship lookup bypasses entity filters. Sales
// operations keep their normal authorization. Mantle also clears invalid preferences.
def orgInfo = ec.service.sync().name('mantle.party.PartyServices.get#PartyOrganizationInfo')
        .parameters([partyId:callerPartyId]).disableAuthz().call()
if (ec.message.hasError()) return
def userOrgIds = orgInfo?.userOrgIds ?: []
def resolvedOrg = orgInfo?.activeOrgId
activeOrgId = resolvedOrg && resolvedOrg != '_NA_' && userOrgIds.contains(resolvedOrg) ? resolvedOrg : null
ec.user.context.activeOrgId = activeOrgId
ec.user.context.userOrgIds = userOrgIds
ec.user.context.filterOrgIds = activeOrgId ? [activeOrgId] : userOrgIds
